            f"   └ Premium +25%: +{premium_gold:.2f}\n"
        )
    else:
        text += f"\n💰 Золото: +{float(reward['gold']):.2f}\n"

    event_drop_messages = _event_drop_victory_messages(
        reward.get("event_drop_results")
