    cooldowns = mob.get("skill_cooldowns") or {}
    cooldown = max(0, int(cooldowns.get(key, 0) or 0))
    if cooldown > 0:
        return _state(
            skill, False, "cooldown",
            f"⏳ {name} · ще {_turns_uk(cooldown)}",
            f"⏳ {name} ще перезаряджається. Залишилось: {_turns_uk(cooldown)}.",
            remaining=cooldown,
        )

    player_stunned = max(0, int(mob.get("player_stunned_turns", 0) or 0))
    player_effects = mob.get("player_effects") or {}
    controlled = player_stunned > 0 or any(
        str(effect.get("type") or "").lower() in {"stun", "silence", "control"}
        and int(effect.get("turns", 0) or 0) > 0
        for effect in player_effects.values()
        if isinstance(effect, dict)
    )
    if controlled:
        return _state(
            skill, False, "control_state",
            f"🔒 {name} · зараз недоступна",
            f"🔒 {name} зараз недоступна через ефект контролю.",
        )

    cost_type = str(skill.get("cost_type") or "")
    cost = get_pve_effective_skill_cost(mob, skill)

    if cost_type == "rage":
        current = max(0, int(mob.get("player_rage", 0) or 0))
        if current < cost:
            return _state(skill, False, "not_enough_rage",
                          f"🔒 {name} · потрібно {cost} Люті",
                          f"🔴 Недостатньо Люті для {name}. Потрібно: {cost}, доступно: {current}.",
                          required=cost, available_amount=current)

    elif cost_type == "rage_all_min":
        required = max(0, int(skill.get("min_cost", 30) or 30))
        current = max(0, int(mob.get("player_rage", 0) or 0))
        if current < required:
            return _state(skill, False, "not_enough_rage",
                          f"🔒 {name} · потрібно {required} Люті",
                          f"🔴 Недостатньо Люті для {name}. Потрібно мінімум: {required}, доступно: {current}.",
                          required=required, available_amount=current)

    elif cost_type in {"combat_energy", "combat_energy_combo"}:
        current = max(0, int(mob.get("player_combat_energy", 0) or 0))
        maximum = max(0, int(mob.get("player_max_combat_energy", 100) or 100))
        projected = min(maximum, current + 20)
        if projected < cost:
            return _state(skill, False, "not_enough_combat_energy",
                          f"🔒 {name} · потрібно {cost} Енергії",
                          f"🟡 Недостатньо Енергії для {name}. Потрібно: {cost}, на початку ходу буде доступно: {projected}.",
                          required=cost, available_amount=projected)
        if cost_type == "combat_energy_combo":
            required_combo = max(1, int(skill.get("min_combo", 1) or 1))
            combo = max(0, int(mob.get("player_combo_points", 0) or 0))
            if combo < required_combo:
                return _state(skill, False, "not_enough_combo",
                              f"🔒 {name} · потрібно {required_combo} комбо",
                              f"⚔️ Недостатньо комбо для {name}. Потрібно: {required_combo}, доступно: {combo}.",
                              required=required_combo, available_amount=combo)

    elif cost_type == "mana":
        current = max(0, int(mob.get("player_mp", 0) or 0))
        maximum = max(0, int(mob.get("player_max_mp", 0) or 0))
        if skill.get("key") == "mage_arcane_flow" and maximum > 0 and current >= maximum:
            return _state(skill, False, "mana_already_full",
                          f"🔒 {name} · Мана вже повна",
                          "🔵 Мана вже повна.",
                          required=cost, available_amount=current, effective_cost=cost)
        if current < cost:
            return _state(skill, False, "not_enough_mana",
                          f"🔒 {name} · потрібно {cost} Мани",
                          f"🔵 Недостатньо Мани для {name}. Потрібно: {cost}, доступно: {current}.",
                          required=cost, available_amount=current, effective_cost=cost)

    return _state(skill, True, "ok", f"✨ {name}", "", effective_cost=cost)

def _parse(value: str | None) -> datetime | None:
    if not value:
        return None
    try:
        parsed = datetime.fromisoformat(str(value))
    except (TypeError, ValueError):
        return None
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    return parsed.astimezone(timezone.utc)

def _loads(value: str | None, fallback: Any) -> Any:
    if not value:
        return fallback
    try:
        return json.loads(value)
    except (TypeError, ValueError):
        return fallback

def configure_pvp_connection_factory(factory: ConnectionFactory | None) -> None:
    global _CONNECTION_FACTORY
    _CONNECTION_FACTORY = factory

def _default_connection() -> sqlite3.Connection:
    try:
        import db as db_module
    except ImportError:
        db_module = None
    if db_module is not None:
        for name in ("get_db_connection", "get_connection", "connect_db", "create_connection"):
            candidate = getattr(db_module, name, None)
            if callable(candidate):
                connection = candidate()
                connection.row_factory = sqlite3.Row
                return connection
        declared_path = getattr(db_module, "DB_PATH", None)
        if declared_path:
            connection = sqlite3.connect(str(declared_path), timeout=30)
            connection.row_factory = sqlite3.Row
            return connection
    root = Path(__file__).resolve().parents[1]
    connection = sqlite3.connect(str(root / "game.db"), timeout=30)
    connection.row_factory = sqlite3.Row
    return connection

def _connection(connection: sqlite3.Connection | None = None):
    owned = connection is None
    conn = connection or (_CONNECTION_FACTORY() if _CONNECTION_FACTORY else _default_connection())
    conn.row_factory = sqlite3.Row
    try:
        yield conn
    finally:
        if owned:
            conn.close()

def _normalized_participant(user_id: int, side: str, snapshot: Mapping[str, Any], now: str) -> tuple[Any, ...]:
    class_key = str(snapshot.get("class_key") or snapshot.get("character_class") or "").strip().lower()
    if not class_key:
        raise ValueError("participant class_key is required")
    max_hp = max(1, int(snapshot.get("max_hp") or 1))
    max_mp = max(0, int(snapshot.get("max_mp") or 0))
    resource_type = str(snapshot.get("resource_type") or "rage")
    resource_value = 100 if resource_type in {"combat_energy", "combat_energy_combo"} else 0
    if resource_type == "mana":
        resource_value = max_mp
    return (
        int(user_id), side, class_key, max_hp, max_hp, max_mp, max_mp,
        resource_type, resource_value, 0, 0, 0, "{}", "{}", _json(dict(snapshot)), now, now,
    )

def submit_pvp_action(
    battle_id: int,
    user_id: int,
    round_number: int,
    revision: int,
    action_type: str,
    skill_key: str | None = None,
    payload: Mapping[str, Any] | None = None,
    connection: sqlite3.Connection | None = None,
) -> dict[str, Any]:
    if action_type not in {"basic_attack", "skill", "afk_skip", "stunned_skip"}:
        raise ValueError("unsupported PvP action type")
    if action_type == "skill" and not skill_key:
        raise ValueError("skill_key is required for skill action")
    with _connection(connection) as conn:
        conn.execute("BEGIN IMMEDIATE")
        try:
            battle = conn.execute("SELECT * FROM pvp_battles WHERE id = ?", (int(battle_id),)).fetchone()
            if not battle or battle["status"] != "active":
                raise ValueError("PvP battle is not active")
            if int(battle["round_number"]) != int(round_number) or int(battle["revision"]) != int(revision):
                raise ValueError("stale PvP callback")
            participant = conn.execute(
                "SELECT 1 FROM pvp_participants WHERE battle_id = ? AND user_id = ?",
                (int(battle_id), int(user_id)),
            ).fetchone()
            if not participant:
                raise ValueError("actor does not belong to this PvP battle")
            conn.execute(
                """
                INSERT INTO pvp_round_actions(
                    battle_id, round_number, revision, user_id, action_type, skill_key, payload_json, submitted_at
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (int(battle_id), int(round_number), int(revision), int(user_id), action_type, skill_key, _json(dict(payload or {})), _iso()),
            )
            count = conn.execute(
                "SELECT COUNT(*) FROM pvp_round_actions WHERE battle_id = ? AND round_number = ? AND revision = ?",
                (int(battle_id), int(round_number), int(revision)),
            ).fetchone()[0]
            add_pvp_event(
                int(battle_id), "action_submitted", int(round_number), int(revision), int(user_id),
                payload={"action_type": action_type, "skill_key": skill_key}, connection=conn,
            )
            conn.commit()
            return {"accepted": True, "actions_ready": int(count), "both_ready": int(count) >= 2}
        except sqlite3.IntegrityError as exc:
            conn.rollback()
            raise ValueError("action already submitted for this round") from exc
        except Exception:
            conn.rollback()
            raise

def get_pvp_recovery_plan(
    now: datetime | None = None,
    connection: sqlite3.Connection | None = None,
) -> dict[str, Any]:
    moment = now or _utc_now()
    with _connection(connection) as conn:
        rows = conn.execute(
            "SELECT * FROM pvp_battles WHERE status IN ('waiting','active','resolving') ORDER BY id"
        ).fetchall()
        active = []
        expired = []
        resolving = []
        for row in rows:
            item = dict(row)
            deadline = _parse(item.get("action_deadline"))
            if item["status"] == "resolving":
                resolving.append(item["id"])
            elif deadline is not None and deadline <= moment:
                expired.append(item["id"])
            else:
                active.append(item["id"])
        return {"active": active, "expired": expired, "resolving": resolving}

def resolve_persisted_pvp_round(battle_id: int, round_number: int, revision: int, seed: int | None = None, connection: sqlite3.Connection | None = None) -> dict[str, Any]:
    """Resolve two persisted intents once and persist only duel-local participant state."""
    from dataclasses import asdict
    from systems.pvp_models import PvpActionIntent, PvpActorState
    from systems.pvp_round_engine import resolve_pvp_round
    with _connection(connection) as conn:
        if not claim_pvp_round_resolution(battle_id, round_number, revision, conn):
            return {"resolved": False, "reason": "resolution_not_claimed"}
        try:
            participants = get_pvp_participants(battle_id, conn)
            actions = get_pvp_round_actions(battle_id, round_number, revision, conn)
            if len(participants) != 2 or len(actions) != 2:
                conn.execute("UPDATE pvp_battles SET status='active', resolving=0 WHERE id=?", (int(battle_id),))
                conn.commit()
                return {"resolved": False, "reason": "actions_or_participants_incomplete"}
            actors = []
            for row in participants:
                snap = dict(row.get("snapshot") or {})
                snap.update({"user_id":row["user_id"],"class_key":row["class_key"],"max_hp":row["max_hp"],"hp":row["hp"],"max_mp":row["max_mp"],"mp":row["mp"],"resource_type":row["resource_type"],"resource":row["resource_value"],"combo":row["combo"],"cooldowns":row["cooldowns"],"effects":row["effects"],"consecutive_afk":row["consecutive_afk"],"stunned_next":bool(row["stunned_next"])})
                actors.append(PvpActorState.from_dict(snap))
            intents = {row["user_id"]: PvpActionIntent(row["user_id"], row["action_type"], row["skill_key"], row["payload"]) for row in actions}
            result = resolve_pvp_round(round_number, revision, actors[0], actors[1], intents[actors[0].user_id], intents[actors[1].user_id], seed=seed)
            for state in (result.actor_a, result.actor_b):
                conn.execute("""UPDATE pvp_participants SET hp=?,mp=?,resource_value=?,combo=?,consecutive_afk=?,stunned_next=?,cooldowns_json=?,effects_json=?,updated_at=? WHERE battle_id=? AND user_id=?""",(state["hp"],state["mp"],state["resource"],state["combo"],state["consecutive_afk"],1 if state["stunned_next"] else 0,_json(state["cooldowns"]),_json(state["effects"]),_iso(),int(battle_id),int(state["user_id"])))
            round_payload = {
                "round_number": result.round_number,
                "revision": result.revision,
                "terminal": result.terminal,
                "winner_id": result.winner_id,
                "reason": result.result_reason,
                "actors": [dict(result.actor_a), dict(result.actor_b)],
                "outcomes": [asdict(outcome) for outcome in result.outcomes],
                "events": list(result.events),
            }
            add_pvp_event(battle_id,"round_resolved",round_number,revision,payload=round_payload,connection=conn)
            if result.terminal:
                complete_pvp_battle(battle_id,result.result_reason or "terminal",result.winner_id,connection=conn)
            else:
                release_pvp_round_resolution(battle_id,revision,connection=conn)
            conn.commit()
            return {
                "resolved": True, "terminal": result.terminal,
                "winner_id": result.winner_id, "result_reason": result.result_reason,
                "round_payload": round_payload,
            }
        except Exception:
            conn.rollback()
            raise
